class Boeing {
  + CompanyName : string
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
  + EmployeeID : string
}

class Salesperson {
  + SalesID : string
}

class Contract {
  + ContractID : string
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + NegotiatedPrice : float
  + Customizations : string
  + DeliveryDate : date
}

class Airplane {
  + SerialNumber : string
  + ModelType : string
}

Airline "1" -- "0..*" Contract
Airline "0..1" -- "0..1" Airline : motherOf
Airline "0..1" -- "0..1" Airline : daughterOf
Contract "1" -- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Employee "1" -- "0..*" Salesperson
Salesperson "1" -- "0..*" Contract
Boeing "1" -- "0..*" Contract

@enduml

